try {
  const { keywords, location, jobType, minSalary, _verifyMode } = params;

  // Check for anti-bot on initial page
  await page.checkAntiBot({ maxWait: 10000 });

  // Fill keywords
  await page.waitForSelector('#text-input-what', { timeout: 8000 });
  await page.randomDelay(800, 1500);
  await page.humanType('#text-input-what', keywords || '');
  await page.randomDelay(500, 1000);

  // Fill location
  if (location) {
    await page.humanType('#text-input-where', location);
    await page.randomDelay(500, 1000);
  }

  // Submit search
  await page.humanClick('button[type="submit"].yosegi-InlineWhatWhere-primaryButton');
  await page.waitForNavigation({ timeout: 15000 });
  await page.checkAntiBot({ maxWait: 10000 });
  await page.randomDelay(1500, 2500);

  // Apply job type filter if specified
  if (jobType) {
    const typeMap = {
      'fulltime': 'fulltime',
      'full-time': 'fulltime',
      'parttime': 'parttime',
      'part-time': 'parttime',
      'contract': 'contract',
      'temporary': 'temporary',
      'internship': 'internship'
    };
    const jtKey = typeMap[(jobType || '').toLowerCase()] || jobType.toLowerCase();
    const currentUrl = await page.url();
    const sep = currentUrl.includes('?') ? '&' : '?';
    await page.goto(currentUrl + sep + 'jt=' + jtKey);
    await page.waitForNavigation({ timeout: 15000 }).catch(() => {});
    await page.checkAntiBot({ maxWait: 10000 });
    await page.randomDelay(1500, 2500);
  }

  // Apply salary filter if specified
  if (minSalary) {
    const currentUrl = await page.url();
    const sep = currentUrl.includes('?') ? '&' : '?';
    // Indeed uses salary param like salary=$60,000+ encoded
    await page.goto(currentUrl + sep + 'salary=' + encodeURIComponent(minSalary));
    await page.waitForNavigation({ timeout: 15000 }).catch(() => {});
    await page.checkAntiBot({ maxWait: 10000 });
    await page.randomDelay(1500, 2500);
  }

  // Wait for job cards to load
  await page.waitForSelector('.job_seen_beacon, .jobsearch-ResultsList .result, .mosaic-provider-jobcards .result', { timeout: 10000 }).catch(() => {});
  await page.randomDelay(1000, 2000);

  // Phase 1: Extract job cards
  const jobs = await page.evaluate(() => {
    const results = [];
    const cards = document.querySelectorAll('.job_seen_beacon, .mosaic-zone .result, div[class*="cardOutline"]');

    cards.forEach(card => {
      try {
        const titleEl = card.querySelector('.jcs-JobTitle, a[class*="JobTitle"]');
        const title = titleEl ? titleEl.textContent.trim() : '';

        let url = '';
        if (titleEl) {
          const link = titleEl.tagName === 'A' ? titleEl : titleEl.closest('a');
          if (link) {
            const rawHref = link.href || '';
            // Prefer the real href; extract jk param for a clean canonical URL
            if (rawHref) {
              try {
                const parsedUrl = new URL(rawHref, 'https://ca.indeed.com');
                const jkParam = parsedUrl.searchParams.get('jk');
                url = jkParam ? 'https://ca.indeed.com/viewjob?jk=' + jkParam : rawHref;
              } catch(e) {
                url = rawHref;
              }
            } else if (link.id) {
              // Fallback: reconstruct from element id (sj_xxxx format)
              const jk = link.id.replace(/^sj_/, '');
              if (jk) url = 'https://ca.indeed.com/viewjob?jk=' + jk;
            }
          }
        }

        const companyEl = card.querySelector('[data-testid="company-name"], .companyName, .company_location .companyName, span[class*="company"]');
        const company = companyEl ? companyEl.textContent.trim() : '';

        const locationEl = card.querySelector('[data-testid="text-location"], .companyLocation, div[class*="company_location"] div[data-testid="text-location"]');
        const loc = locationEl ? locationEl.textContent.trim() : '';

        const salaryEl = card.querySelector('.salary-snippet-container, div[class*="salary"], .metadata.salary-snippet-container, [class*="SalarySnippet"], div[class*="salaryOnly"]');
        const salary = salaryEl ? salaryEl.textContent.trim() : '';

        const snippetEl = card.querySelector('.job-snippet, td.snip .job-snippet, [class*="JobSnippet"], ul[style]');
        const description = snippetEl ? snippetEl.textContent.trim() : '';

        if (title) {
          results.push({
            title,
            company,
            url,
            location: loc,
            salary,
            description,
            fullText: ''
          });
        }
      } catch (e) {
        // skip bad card
      }
    });

    return results;
  });

  // Phase 2: JD Detail Extraction
  if (_verifyMode) {
    jobs.forEach(j => { j.fullText = ''; });
  } else {
    for (let i = 0; i < jobs.length; i++) {
      try {
        // Click the job card title to open split-pane detail
        const titleSelectors = '.jcs-JobTitle, a[class*="JobTitle"]';
        const allTitles = await page.$$(titleSelectors);
        if (allTitles && allTitles.length > i) {
          const sel = typeof allTitles[i] === 'string' ? allTitles[i] : titleSelectors + `:nth-of-type(${i + 1})`;
          // Use evaluate to click the i-th title
          await page.evaluate((idx) => {
            const titles = document.querySelectorAll('.jcs-JobTitle, a[class*="JobTitle"]');
            if (titles[idx]) titles[idx].click();
          }, i);

          await page.randomDelay(1500, 3000);

          // Extract full job description from the detail panel
          const fullText = await page.evaluate(() => {
            const selectors = [
              '#jobDescriptionText',
              '.jobsearch-JobComponent-description',
              '[class*="jobDescription"]',
              '.jobsearch-jobDescriptionText',
              '#jobDescriptionText .jobsearch-JobComponent-description'
            ];
            for (const sel of selectors) {
              const el = document.querySelector(sel);
              if (el && el.textContent.trim().length > 50) {
                return el.textContent.trim();
              }
            }
            // Fallback: try the right pane
            const rightPane = document.querySelector('.jobsearch-RightPane, [class*="RightPane"], .jobsearch-ViewJobLayout--inline');
            if (rightPane) return rightPane.textContent.trim();
            return '';
          });

          jobs[i].fullText = fullText || '';
        }
      } catch (e) {
        jobs[i].fullText = '';
      }
    }
  }

  return { success: true, jobs };

} catch (error) {
  return { success: false, error: error.message || String(error) };
}

try {
  const maxResults = Math.max(1, Number(params.maxResults) || 30);
  const pageOffset = Math.max(0, Number(params.pageOffset) || 0);
  const keywords = (params.keywords || "").trim();
  const location = params.location == null ? "" : String(params.location).trim();
  const minSalary = params.minSalary != null && params.minSalary !== "" ? Number(params.minSalary) : null;

  const normalizeUrl = (href, baseUrl) => {
    try {
      const u = new URL(href, baseUrl);
      u.searchParams.delete("trackingId");
      u.searchParams.delete("refId");
      u.searchParams.delete("midToken");
      u.searchParams.delete("trk");
      return u.toString();
    } catch {
      return href || "";
    }
  };

  const cssEscape = (value) =>
    String(value).replace(/\\/g, "\\\\").replace(/"/g, '\\"');

  const mapJobType = (value) => {
    if (!value) return "";
    const raw = String(value).trim().toLowerCase();
    const map = {
      "full-time": "F",
      fulltime: "F",
      full: "F",
      "part-time": "P",
      parttime: "P",
      part: "P",
      contract: "C",
      temporary: "T",
      temp: "T",
      internship: "I",
      intern: "I",
      volunteer: "V",
      other: "O"
    };
    return map[raw] || "";
  };

  const parseSalaryNumber = (text) => {
    if (!text) return null;
    const matches = String(text).match(/(?:CA?\$|US?\$|£|€)?\s?(\d{2,3}(?:,\d{3})+|\d{2,3})/g);
    if (!matches || !matches.length) return null;
    const values = matches
      .map((m) => {
        const n = m.replace(/[^\d]/g, "");
        return n ? Number(n) : null;
      })
      .filter((n) => Number.isFinite(n));
    return values.length ? Math.max(...values) : null;
  };

  const jobCardSelectors = [
    'a[href*="/jobs/view/"]',
    '.job-card-container',
    '.jobs-search-results__list-item',
    '[data-job-id]',
    '.base-card'
  ];

  const verifyPageNotBlocked = async () => {
    const check = await page.evaluate((selectors) => {
      const title = document.title || "";
      if (title.includes("Just a moment")) {
        return { blocked: true, reason: "Cloudflare challenge detected (title: '" + title + "')" };
      }
      const hasJobCard = selectors.some((sel) => !!document.querySelector(sel));
      if (!hasJobCard) {
        return { blocked: true, reason: "No job card selector found on page — possible Cloudflare block or broken selector. Page title: '" + title + "'" };
      }
      return { blocked: false };
    }, jobCardSelectors);

    if (check.blocked) {
      throw new Error(check.reason);
    }
  };

  // Dismiss LinkedIn Premium upsell overlay/panel that replaces the job detail pane
  const dismissPremiumOverlay = async () => {
    // Primary approach: JS-based click search — handles cases where Puppeteer element
    // handles fail visibility checks but the button is still present in the DOM.
    const dismissed = await page.evaluate(() => {
      // Find any visible dismiss/close button associated with the premium panel
      const allButtons = Array.from(document.querySelectorAll("button"));
      for (const btn of allButtons) {
        const label = (btn.getAttribute("aria-label") || "").toLowerCase();
        const controlName = (btn.getAttribute("data-control-name") || "").toLowerCase();
        const classStr = (btn.className || "").toLowerCase();
        const btnText = (btn.textContent || "").trim();

        const isDismiss =
          label.includes("dismiss") ||
          label.includes("close") ||
          controlName.includes("dismiss") ||
          classStr.includes("dismiss") ||
          btnText === "×" ||
          btnText === "✕";

        if (!isDismiss) continue;

        const rect = btn.getBoundingClientRect();
        if (rect.width === 0 && rect.height === 0) continue;

        // Check if it's near a premium upsell section
        const container = btn.closest(
          '[class*="premium"], [class*="upsell"], [class*="artdeco-modal"], .jobs-search__right-rail, [data-test-modal]'
        );
        const bodyText = document.body?.innerText || "";
        const premiumVisible = /job search smarter with premium|try premium|premium for ca/i.test(bodyText);

        if (container || premiumVisible) {
          btn.click();
          return true;
        }
      }

      // Fallback: if Premium content visible, click any dismiss/close button anywhere
      const bodyText = document.body?.innerText || "";
      if (/job search smarter with premium|try premium|premium for ca/i.test(bodyText)) {
        // Try generic close buttons
        const genericClose = document.querySelector(
          '.artdeco-modal__dismiss, button[aria-label="Dismiss"], button[aria-label="Close"]'
        );
        if (genericClose) {
          genericClose.click();
          return true;
        }
      }

      return false;
    });

    if (dismissed) {
      await page.randomDelay(800, 1400);
      return true;
    }

    // Secondary approach: try Puppeteer element handles with extended selector list
    const closeSelectors = [
      '[data-test-modal] button[aria-label*="Dismiss" i]',
      '[data-test-modal] button[aria-label*="Close" i]',
      '[data-test-modal] .artdeco-modal__dismiss',
      'button[aria-label*="Dismiss" i][data-control-name*="premium" i]',
      '.jobs-premium-upsell-card__dismiss',
      '.jobs-premium-upsell-card button[aria-label*="Dismiss" i]',
      '.jobs-premium-upsell-card button[aria-label*="Close" i]',
      '.artdeco-modal__dismiss',
      '.artdeco-modal .artdeco-modal__dismiss',
      '.jobs-search__right-rail button[aria-label*="Dismiss" i]',
      '.jobs-search__right-rail button[aria-label*="Close" i]',
      'button[aria-label="Dismiss"]',
      'button[aria-label="Close"]',
    ];

    for (const sel of closeSelectors) {
      try {
        const el = await page.$(sel);
        if (el) {
          const visible = await page.evaluate((el) => {
            const rect = el.getBoundingClientRect();
            const style = window.getComputedStyle(el);
            return rect.width > 0 && rect.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
          }, el);
          if (visible) {
            await el.click();
            await page.randomDelay(800, 1400);
            return true;
          }
          // Try JS click even if visibility check failed
          await page.evaluate((el) => el.click(), el);
          await page.randomDelay(800, 1400);
          return true;
        }
      } catch {
        // ignore and try next selector
      }
    }

    // Last resort: Escape key
    const hasPremiumPanel = await page.evaluate(() => {
      const bodyText = (document.body?.innerText || "");
      return /job search smarter with premium|try premium|premium for ca/i.test(bodyText);
    });

    if (hasPremiumPanel) {
      await page.keyboard.press("Escape");
      await page.randomDelay(800, 1400);
    }

    return false;
  };

  const waitForResultsOrEmpty = async (timeoutMs) => {
    const started = Date.now();
    while (Date.now() - started < timeoutMs) {
      const state = await page.evaluate(() => {
        const jobAnchors = Array.from(document.querySelectorAll('a[href*="/jobs/view/"]'))
          .filter((a) => {
            const href = a.getAttribute("href") || "";
            const text = (a.textContent || "").trim();
            return href.includes("/jobs/view/") && text.length > 0 && a.offsetParent !== null;
          });

        const bodyText = (document.body?.innerText || "").toLowerCase();
        const noResults =
          /no results|0 results|no matching jobs|no jobs found|try different keywords/.test(bodyText) ||
          !!document.querySelector('[data-test-empty-state], .jobs-search-no-results, .artdeco-empty-state');

        return {
          hasResults: jobAnchors.length > 0,
          noResults,
          count: jobAnchors.length
        };
      });

      if (state.hasResults || state.noResults) return state;
      await page.waitForTimeout(700);
    }
    return { hasResults: false, noResults: false, count: 0 };
  };

  const clearOrRetypeLocationIfNeeded = async () => {
    const locationSelectors = [
      'input[aria-label*="City" i]',
      'input[aria-label*="location" i]',
      'input[placeholder*="City" i]',
      'input[placeholder*="location" i]'
    ];

    for (const selector of locationSelectors) {
      if (await page.$(selector)) {
        await page.waitForSelector(selector, { timeout: 7000, visible: true });
        await page.humanType(selector, location || "");
        await page.randomDelay(800, 1400);
        await page.keyboard.press("Enter");
        await page.randomDelay(1500, 3000);
        return true;
      }
    }

    const clearSelectors = [
      'button[aria-label*="Clear" i]',
      'a[aria-label*="Clear" i]',
      'button[title*="Clear" i]'
    ];

    for (const selector of clearSelectors) {
      if (await page.$(selector)) {
        await page.waitForSelector(selector, { timeout: 5000, visible: true });
        await page.humanClick(selector);
        await page.randomDelay(1500, 3000);
        return true;
      }
    }

    return false;
  };

  const resultsPerPage = 25;
  const start = pageOffset * resultsPerPage;

  // Use the standard LinkedIn jobs search URL (not /jobs/search-results/ which behaves differently)
  const url = new URL("https://www.linkedin.com/jobs/search/");
  url.searchParams.set("keywords", keywords);
  url.searchParams.set("location", location);
  url.searchParams.set("start", String(start));

  const jobTypeCode = mapJobType(params.jobType);
  if (jobTypeCode) url.searchParams.set("f_JT", jobTypeCode);

  await page.goto(url.toString());
  await page.checkAntiBot({ maxWait: 10000 });
  await page.randomDelay(1000, 1800);

  await page.waitForSelector("body", { timeout: 8000, visible: true });

  // Verify the page is not a Cloudflare challenge and has job card selectors
  await verifyPageNotBlocked();

  // Dismiss LinkedIn Premium upsell overlay before collecting results
  // Attempt multiple times in case it appears after initial page load
  for (let attempt = 0; attempt < 3; attempt++) {
    const wasDismissed = await dismissPremiumOverlay();
    if (!wasDismissed) break;
    await page.randomDelay(600, 1000);
  }

  let state = await waitForResultsOrEmpty(12000);

  if (state.noResults || !state.hasResults) {
    await page.screenshot();
    const recovered = await clearOrRetypeLocationIfNeeded();
    if (recovered) {
      // Dismiss overlay again in case it reappeared after navigation
      await dismissPremiumOverlay();
      await page.randomDelay(400, 800);
      state = await waitForResultsOrEmpty(12000);
    }
    if (state.noResults || !state.hasResults) {
      // Re-verify before returning empty — distinguish true no-results from a block
      await verifyPageNotBlocked();
      return { success: true, jobs: [] };
    }
  }

  const cardSelector = 'a[href*="/jobs/view/"]';

  let previousCount = 0;
  for (let i = 0; i < 8; i++) {
    const currentCount = (await page.$$(cardSelector)).length;
    if (currentCount >= maxResults) break;

    // Dismiss any Premium overlay before scrolling
    await dismissPremiumOverlay();

    await page.evaluate(() => {
      const selectors = [
        ".jobs-search-results-list",
        ".scaffold-layout__list",
        '[data-results-list-container]',
        ".jobs-search-results__list",
        "main"
      ];

      let container = null;
      for (const selector of selectors) {
        const el = document.querySelector(selector);
        if (el && el.scrollHeight > el.clientHeight) {
          container = el;
          break;
        }
      }

      if (!container) {
        const candidates = Array.from(document.querySelectorAll("div, section, main"))
          .filter((el) => el.scrollHeight > el.clientHeight + 100)
          .sort((a, b) => b.scrollHeight - a.scrollHeight);
        container = candidates[0] || document.scrollingElement || document.body;
      }

      const nextTop = Math.min(
        container.scrollTop + Math.max(600, Math.floor(container.clientHeight * 0.9)),
        container.scrollHeight
      );
      container.scrollTo({ top: nextTop, behavior: "smooth" });
    });

    await page.randomDelay(1500, 2500);

    // Dismiss overlay if it reappears mid-scroll
    await dismissPremiumOverlay();

    const newCount = (await page.$$(cardSelector)).length;
    if (newCount <= previousCount || newCount === currentCount) break;
    previousCount = newCount;
  }

  const jobs = await page.$$eval(
    cardSelector,
    (anchors, limit, baseUrl) => {
      const normalize = (href) => {
        try {
          const u = new URL(href, baseUrl);
          u.searchParams.delete("trackingId");
          u.searchParams.delete("refId");
          u.searchParams.delete("midToken");
          u.searchParams.delete("trk");
          return u.toString();
        } catch {
          return href || "";
        }
      };

      const out = [];
      const seen = new Set();

      for (const a of anchors) {
        if (out.length >= limit) break;
        if (!(a instanceof HTMLAnchorElement)) continue;
        if (a.offsetParent === null) continue;

        const rawHref = a.href || a.getAttribute("href") || "";
        if (!rawHref || !rawHref.includes("/jobs/view/")) continue;

        const url = normalize(rawHref);
        if (!url || seen.has(url)) continue;
        seen.add(url);

        const container =
          a.closest("li") ||
          a.closest("article") ||
          a.closest('[class*="job"]') ||
          a.closest("div");

        const text = (container?.innerText || a.innerText || "").replace(/\u00a0/g, " ").trim();
        const lines = text
          .split("\n")
          .map((s) => s.trim())
          .filter(Boolean);

        const title = (a.textContent || lines[0] || "").trim();
        let company = "";
        let location = "";
        let salary = "";
        let description = "";

        const moneyLine = lines.find((line) => /(?:CA?\$|US?\$|£|€|\bper year\b|\byr\b|\bhour\b)/i.test(line));
        if (moneyLine) salary = moneyLine;

        for (const line of lines) {
          if (!company && line !== title && !/(promoted|easy apply|actively reviewing|be an early applicant)/i.test(line)) {
            company = line;
            continue;
          }
          if (!location && line !== title && line !== company && /[,]|remote|hybrid|on-site|onsite/i.test(line)) {
            location = line;
            continue;
          }
        }

        description = lines
          .filter((line) => ![title, company, location, salary].includes(line))
          .slice(0, 3)
          .join(" ")
          .trim();

        const jobKey = String(out.length);
        a.setAttribute("data-job-key", jobKey);

        out.push({
          jobKey,
          title,
          company,
          url,
          location,
          salary,
          description,
          fullText: ""
        });
      }

      return out;
    },
    maxResults,
    "https://www.linkedin.com"
  );

  const filteredJobs = minSalary
    ? jobs.filter((job) => {
        const value = parseSalaryNumber(job.salary);
        return value == null || value >= minSalary;
      })
    : jobs;

  if (params._verifyMode) {
    filteredJobs.forEach((job) => {
      job.fullText = "";
      delete job.jobKey;
    });
    return { success: true, jobs: filteredJobs };
  }

  for (const job of filteredJobs) {
    try {
      const selector = `a[data-job-key="${cssEscape(job.jobKey)}"]`;

      if (await page.$(selector)) {
        await page.waitForSelector(selector, { timeout: 7000, visible: true });
        await page.humanClick(selector);
        await page.randomDelay(1500, 3000);

        // Dismiss any Premium overlay that appears after clicking a job
        await dismissPremiumOverlay();
        await page.randomDelay(500, 800);

        const fullText = await page.evaluate(() => {
          const isVisible = (el) => {
            const rect = el.getBoundingClientRect();
            const style = window.getComputedStyle(el);
            return (
              rect.width > 200 &&
              rect.height > 120 &&
              style.visibility !== "hidden" &&
              style.display !== "none"
            );
          };

          const candidates = Array.from(document.querySelectorAll("main, section, article, div"))
            .filter((el) => {
              if (!isVisible(el)) return false;
              const rect = el.getBoundingClientRect();
              const text = (el.innerText || "").trim();
              // Exclude the premium upsell panel itself from being picked as job detail
              const isPremiumPanel = /job search smarter with premium|try premium for ca/i.test(text) &&
                text.length < 800;
              return !isPremiumPanel && rect.x > window.innerWidth * 0.25 && text.length > 300;
            })
            .map((el) => ({
              text: (el.innerText || "").replace(/\n{3,}/g, "\n\n").trim(),
              score: ((el.innerText || "").trim().length) + Math.max(0, el.getBoundingClientRect().x)
            }))
            .sort((a, b) => b.score - a.score);

          return candidates[0]?.text || "";
        });

        job.fullText = fullText || "";
        if (!job.description && job.fullText) {
          job.description = job.fullText.slice(0, 280).trim();
        }
        if (!job.salary && job.fullText) {
          const salaryLine = job.fullText
            .split("\n")
            .map((s) => s.trim())
            .find((line) => /(?:CA?\$|US?\$|£|€|\bper year\b|\byr\b|\bhour\b)/i.test(line));
          if (salaryLine) job.salary = salaryLine;
        }
      } else {
        job.fullText = "";
      }
    } catch {
      job.fullText = "";
    }

    delete job.jobKey;
  }

  return { success: true, jobs: filteredJobs };
} catch (error) {
  return {
    success: false,
    error: error && error.message ? error.message : String(error)
  };
}

try {
  const {
    keywords = '',
    location = '',
    jobType = '',
    minSalary = 0,
    maxResults = 30,
    pageOffset = 0,
    _verifyMode = false
  } = params;

  // Build search URL
  const jobTypeMap = {
    'full-time': 'fulltime', 'fulltime': 'fulltime',
    'part-time': 'parttime', 'parttime': 'parttime',
    'contract': 'contract', 'temporary': 'temporary',
    'internship': 'internship', 'casual': 'casual'
  };
  const jtCode = jobTypeMap[(jobType || '').toLowerCase().trim()];

  const qs = new URLSearchParams();
  qs.set('q', keywords);
  qs.set('l', location); // Always include, even if empty — overrides stale cookie location
  if (jtCode) qs.set('sc', `0kf:jt(${jtCode});`);
  if (minSalary && minSalary > 0) qs.set('salaryMin', String(minSalary));
  const offset = (pageOffset || 0) * 10;
  if (offset > 0) qs.set('start', String(offset));

  const searchUrl = `https://ca.indeed.com/jobs?${qs.toString()}`;
  await page.goto(searchUrl);
  await page.checkAntiBot({ maxWait: 15000 });
  await page.randomDelay(1500, 2500);

  // Wait for results OR no-results — never blindly wait for cards
  const CARD_SEL = '.job_seen_beacon, .tapItem';
  let hasResults = false;

  const detected = await Promise.race([
    page.waitForSelector(CARD_SEL, { timeout: 10000, visible: true }).then(() => 'cards'),
    page.waitForSelector(
      '[class*="NoResult"], [class*="noResult"], [class*="zero-result"], .jobsearch-NoResult',
      { timeout: 10000, visible: true }
    ).then(() => 'noresult')
  ]).catch(() => 'timeout');

  if (detected === 'cards') {
    hasResults = true;
  } else if (detected === 'noresult' || detected === 'timeout') {
    // Try clearing stale location pill
    const pill = await page.$('[data-testid="search-filter-chip"] button, .css-1wx02nd button');
    if (pill) {
      await page.humanClick('[data-testid="search-filter-chip"] button, .css-1wx02nd button');
      await page.randomDelay(1000, 2000);
      const retry = await page.$(CARD_SEL);
      hasResults = !!retry;
    }
    if (!hasResults) return { success: true, jobs: [] };
  }

  // Scroll to load more cards up to maxResults
  const target = Math.min(maxResults, 50);
  for (let s = 0; s < 5; s++) {
    const before = (await page.$$(CARD_SEL)).length;
    if (before >= target) break;
    await page.evaluate(() => window.scrollBy(0, 600));
    await page.randomDelay(1500, 2500);
    const after = (await page.$$(CARD_SEL)).length;
    if (after === before) break;
  }

  // Phase 1 — extract job list
  const JOB_TYPE_RE = /\b(full[- ]?time|part[- ]?time|contract|temporary|internship|casual|on call|seasonal)\b/i;
  const SALARY_RE = /[\$\£\€]|CAD|\/yr|\/hr|\/hour|per year|per hour|a year|an hour|\d+[kK]\/yr|\d+\s*(k|K)\b/;

  const jobs = await page.$$eval(CARD_SEL, (cards, maxCount, SALARY_PAT, JT_PAT) => {
    const salaryRe = new RegExp(SALARY_PAT, 'i');
    const jtRe = new RegExp(JT_PAT, 'i');

    return cards.slice(0, maxCount).map(card => {
      // Title + URL
      const titleEl = card.querySelector('a.jcs-JobTitle, a[class*="jcs-JobTitle"]');
      const title = titleEl ? titleEl.textContent.trim() : '';

      let url = '';
      if (titleEl) {
        const href = titleEl.getAttribute('href') || '';
        if (href.includes('/viewjob')) {
          url = 'https://ca.indeed.com' + href.split('?')[0] + '?jk=' + (new URLSearchParams(href.split('?')[1] || '')).get('jk');
          // Simpler: just use full href resolved
          url = href.startsWith('http') ? href : 'https://ca.indeed.com' + href;
        } else if (href.startsWith('/pagead/') || href.startsWith('/rc/')) {
          // Derive canonical URL from element id: sj_JOBKEY
          const elemId = titleEl.id || '';
          const jobKey = elemId.replace(/^sj_/, '');
          url = jobKey ? `https://ca.indeed.com/viewjob?jk=${jobKey}` : 'https://ca.indeed.com' + href;
        } else if (href.startsWith('http')) {
          url = href;
        } else {
          url = 'https://ca.indeed.com' + href;
        }
      }

      // Company
      const companyEl = card.querySelector('[data-testid="company-name"], .companyName, [class*="companyName"]');
      const company = companyEl ? companyEl.textContent.trim() : '';

      // Location
      const locationEl = card.querySelector('[data-testid="text-location"], .companyLocation, [class*="companyLocation"]');
      const location = locationEl ? locationEl.textContent.trim() : '';

      // Salary & jobType — scan all metadata snippets
      let salary = '';
      let jobType = '';

      // Dedicated salary container first
      const salaryContainer = card.querySelector(
        '.salary-snippet-container, [data-testid="jobcard-salary"], [class*="salarySnippet"], [class*="salary-snippet"]'
      );
      if (salaryContainer) salary = salaryContainer.textContent.trim();

      // All attribute snippets
      const snippets = card.querySelectorAll(
        '[data-testid="attribute_snippet_testid"], .metadata, [class*="attribute_snippet"], .metadataContainer span'
      );
      snippets.forEach(el => {
        const text = el.textContent.trim();
        if (!text) return;
        if (!salary && salaryRe.test(text)) salary = text;
        if (!jobType && jtRe.test(text) && !salaryRe.test(text)) jobType = text;
      });

      // Description snippet
      const descEl = card.querySelector('.job-snippet, [class*="job-snippet"], [class*="snippet"]');
      const description = descEl ? descEl.textContent.replace(/\s+/g, ' ').trim() : '';

      // Ensure salary doesn't bleed job type
      if (salary && jtRe.test(salary) && !SALARY_PAT.split('|').some(p => new RegExp(p, 'i').test(salary))) {
        if (!jobType) jobType = salary;
        salary = '';
      }

      return { title, company, url, location, salary, jobType, description, fullText: '' };
    });
  }, target, SALARY_RE.source, JOB_TYPE_RE.source);

  // Phase 2 — full JD extraction via split-pane click
  if (_verifyMode) {
    jobs.forEach(j => { j.fullText = ''; });
  } else {
    const DETAIL_SEL = '#jobDescriptionText, .jobsearch-JobComponent-description, [class*="jobDescriptionText"]';

    for (let i = 0; i < jobs.length; i++) {
      try {
        // Click the nth job card to load detail pane
        await page.evaluate((idx, cardSel) => {
          const cards = document.querySelectorAll(cardSel);
          if (!cards[idx]) return;
          const link = cards[idx].querySelector('a.jcs-JobTitle, a[class*="jcs-JobTitle"]');
          if (link) link.click();
        }, i, CARD_SEL);

        await page.randomDelay(1500, 3000);

        // Wait for detail pane to populate
        await page.waitForSelector(DETAIL_SEL, { timeout: 8000, visible: true });

        const fullText = await page.evaluate((sel) => {
          const el = document.querySelector(sel);
          return el ? (el.innerText || el.textContent || '').trim() : '';
        }, DETAIL_SEL);

        jobs[i].fullText = fullText;

        await page.randomDelay(800, 1500);
      } catch (e) {
        jobs[i].fullText = '';
      }
    }
  }

  return { success: true, jobs };
} catch (err) {
  return { success: false, error: err.message };
}
